function count(strings, ...values) {
  return `${strings.length}:${values.length}:${strings[0] === ""}`;
}

function sum(strings, ...values) {
  return values.reduce((total, value) => total + value, 0);
}

console.log(count`${"a"} and ${"b"}`);
console.log(count`no values`);
console.log(sum`${1}+${2}=${"?"}`);
console.log(typeof sum`${2}${3}`);
